internal static class EnemyHealthVerification {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Var(List<byte> b,uint value){do{byte n=(byte)(value&127);value>>=7;b.Add((byte)(n|(value!=0?128:0)));}while(value!=0);}
    static byte[] Spawn(uint actor,uint current=119700,uint maximum=119700,uint npc=2100752){var b=new List<byte>{0x41,0x36};Var(b,actor);b.AddRange(new byte[3]);b.AddRange(BitConverter.GetBytes(npc));b.AddRange(new byte[21]);Var(b,current);Var(b,maximum);b.AddRange(new byte[52]);return b.ToArray();}
    static byte[] Energy(uint actor){var b=new List<byte>{0,0x8d};Var(b,actor);b.AddRange(new byte[]{1,1,3});b.AddRange(BitConverter.GetBytes(139100u));return b.ToArray();}
    static byte[] Hp(uint actor,uint current){var b=new List<byte>{0,0x8d};Var(b,actor);b.AddRange(new byte[]{2,1,0});b.AddRange(BitConverter.GetBytes((long)current));return b.ToArray();}
    static byte[] Select(uint actor){var b=new List<byte>{0x34,0x38,0,0,0};Var(b,actor);return b.ToArray();}
    static byte[] Aim(uint actor,uint target,uint skill){var b=new List<byte>{2,0x38};Var(b,actor);b.Add(0);b.AddRange(BitConverter.GetBytes(skill));b.AddRange(new byte[]{0,2});Var(b,target);b.AddRange(BitConverter.GetBytes(0f));b.AddRange(BitConverter.GetBytes(93348f));b.AddRange(BitConverter.GetBytes(26545f));b.AddRange(BitConverter.GetBytes(26728f));return b.ToArray();}
    static void Feed(EnemyHealthSignal signal,byte[] b,double time,string flow="A"){signal.Consume(b,0,b.Length,time,flow);}
    internal static void Run(string root){
        VerifyTextPresentation(root);
        EnemyHealthSignal.Sample special;var nightmare=Spawn(23146,1200000,1200000,2980240);Check(EnemyHealthSignal.Spawn(nightmare,0,nightmare.Length,out special)&&special.Npc==2980240&&special.Maximum==1200000,"Pesadilla NPC namespace retains explicit current/max instead of dropping valid special-instance enemies");var unsupported=Spawn(23146,10,10,3000000);Check(!EnemyHealthSignal.Spawn(unsupported,0,unsupported.Length,out special),"Expanded namespace still rejects unsupported identifiers");
        var signal=new EnemyHealthSignal();signal.Configure(true);Feed(signal,Energy(1923),100);Feed(signal,Spawn(34411),100);Feed(signal,Spawn(21922),100);
        Check(signal.Read()==null,"Spawn alone cannot choose an enemy");Feed(signal,Aim(1923,34411,15110340),101);Check(signal.Read().Actor==34411&&signal.Read().Maximum==119700,"Primary area aim selects explicit max");
        Feed(signal,Aim(1923,21922,15780007),101.1);Feed(signal,Aim(1923,1923,15760007),101.2);Feed(signal,Aim(1923,21922,15750007),101.3);Check(signal.Read().Actor==34411,"Procs, heals and retaliation cannot change primary target");
        Feed(signal,Hp(21922,85941),102);Feed(signal,Hp(34411,98460),102);Check(signal.Read().Current==98460,"Only tracked enemy HP shown");
        Feed(signal,Select(21922),103);Check(signal.Read().Actor==21922&&signal.Read().Locked,"Hard lock overrides soft target");Feed(signal,Aim(1923,34411,15110340),104);Check(signal.Read().Actor==21922,"Attacks do not override lock");Feed(signal,Hp(21922,0),105);Check(signal.Read()==null,"Locked target death hides without falling back to an old area target");
        Feed(signal,Select(34411),106);Check(signal.Read()!=null,"Tab can select existing NPC without attack");Feed(signal,Select(0),107);Check(signal.Read()==null,"Unlock clears old target");
        Feed(signal,Aim(1923,34411,15110340),108,"B");Feed(signal,Spawn(34411,1,10),108,"B");Check(signal.Read()==null,"Other flow cannot borrow self or target IDs");Feed(signal,Aim(1923,34411,15110340),109);Check(signal.Read().Maximum==119700,"Flow isolation");Check(EnemyHealthSignal.Fresh(signal.Read(),118)&&!EnemyHealthSignal.Fresh(signal.Read(),120),"Traffic freshness including clock skew");
        var serializer=new JavaScriptSerializer();var original=new EnemyHealthOptions();original.Bounds=new Rectangle(-400,180,360,6);original.Bar.MediumColor="#CC1122";var saved=EnemyHealthOptions.Read(serializer.Deserialize<Dictionary<string,object>>(serializer.Serialize(new{enemyHealth=original})));Check(saved.Bounds==original.Bounds&&saved.Bar.MediumColor==original.Bar.MediumColor&&!saved.Bar.AutoHide,"Persistence and no full-HP auto hide");var copy=saved.Copy();copy.Bar.TextSize=21;Check(saved.Bar.TextSize!=copy.Bar.TextSize,"Independent deep copy");copy.Name.FontSize=12;copy.Name.OffsetX=80;copy.Name.OffsetY=-180;copy.Name.Position=5;Check(saved.Name.FontSize==21&&saved.Name.OffsetX==-5,"Independent name deep copy");var titleBounds=EnemyNameOverlay.CaptionBounds(new Rectangle(100,200,420,6),copy.Name);Check(titleBounds.Y==34&&titleBounds.Width==430,"Free name offsets are not clipped to bar bounds");var nameSaved=EnemyHealthOptions.Read(serializer.Deserialize<Dictionary<string,object>>(serializer.Serialize(new{enemyHealth=copy})));Check(nameSaved.Name.FontSize==12&&nameSaved.Name.OffsetX==80&&nameSaved.Bar.TextSize==21,"Independent name persistence");using(var displaced=EnemyHealthOverlay.RenderPreview(420,.65,copy,new BarDesign.GlowWorkspace(),"es"))Check(displaced.Height>copy.Bounds.Height+87,"Preview must expand for displaced name");
        var rng=new Random(43);for(int i=0;i<3000;i++){var b=new byte[rng.Next(2,250)];rng.NextBytes(b);int[] ops={0x4136,0x008d,0x3438,0x0238};int op=ops[i%4];b[0]=(byte)(op>>8);b[1]=(byte)op;Feed(signal,b,110+i*.0001);}signal.Reset();Check(signal.Read()==null,"Transport reset clears references");signal.Configure(false);Feed(signal,Energy(1923),200);Check(signal.Read()==null,"Disabled module ignores data");
        var workspace=new BarDesign.GlowWorkspace();using(var bitmap=EnemyHealthOverlay.RenderPreview(612,.738,new EnemyHealthOptions{Bounds=new Rectangle(0,0,612,8)},workspace,"es")){var path=Path.Combine(root,"designs");Directory.CreateDirectory(path);bitmap.Save(Path.Combine(path,"enemy-health-functional-preview.png"));}
        Check(EnemyNames.Name(2100752,"es")=="Karnif de la Meseta","Embedded localized name catalogue");using(var owner=new EnergyOverlay(root,true)){var settings=new HelperSettings(owner);try{settings.VerifyEnemyHealth(root);settings.VerifyEnemyTextOptions(root);}finally{settings.Close();}}
        File.WriteAllText(Path.Combine(root,"enemy-health-test.txt"),"PASS: primary aim/area isolation; passive and self-heal exclusion; Tab/clear; actual HP/max; death; flow/freshness/reset; settings deep copy/persistence; configurable crisp black outlines, alpha/padding/pixel checks and independent metadata/lock-status controls; Tab-only visibility defaults and save/undo; malformed parser fuzz; embedded names and rendering; independent EN/ES settings and undo.");
