    static int DarkPixels(Bitmap image){int count=0;for(int y=0;y<image.Height;y++)for(int x=0;x<image.Width;x++){var p=image.GetPixel(x,y);if(p.A>0&&p.R<10&&p.G<10&&p.B<10)count++;}return count;}
    static Bitmap TextSample(CrispOverlayText text,int width,int opacity){var result=new Bitmap(250,70,System.Drawing.Imaging.PixelFormat.Format32bppPArgb);using(var g=Graphics.FromImage(result)){g.Clear(Color.Transparent);text.Draw(g,"45 · Feras  14 m",22,true,Color.White,new Rectangle(12,12,220,45),0,false,new TextOutlineOptions{Enabled=width>0,Width=Math.Max(1,width),Opacity=opacity});}return result;}
    static void VerifyTextPresentation(string root){
        var original=new EnemyHealthOptions();Check(!original.OnlyLocked&&!EnemyHealthOptions.TargetDefaults().OnlyLocked&&!original.Name.Outline.Enabled&&!original.Bar.TextOutline.Enabled,"Legacy appearance and unlocked target selection remain defaults");var sample=new EnemyHealthSignal.Sample{Distance=14};Check(EnemyHealthOverlay.SelectionAllowed(original,sample),"Ordinary attacks visible by default");original.OnlyLocked=true;Check(!EnemyHealthOverlay.SelectionAllowed(original,sample),"Lock-only mode hides ordinary attacks");sample.Locked=true;Check(EnemyHealthOverlay.SelectionAllowed(original,sample),"Tab target remains eligible even when it has metres");sample.Locked=false;Check(!EnemyHealthOverlay.SelectionAllowed(original,sample),"Unlock hides again");Check(EnemyHealthOverlay.LockCaption(true,"es")=="Bloqueado"&&EnemyHealthOverlay.LockCaption(false,"en")=="Unlocked","Independent lock status reports both states");
        original.Name.Outline.Enabled=true;original.Name.Outline.Width=3;original.Details.DistanceText.Outline.Enabled=true;original.Details.DistanceText.Outline.Opacity=45;original.Details.SpeciesText.Bold=true;original.LockText.Outline.Enabled=true;original.Bar.TextOutline.Enabled=true;var copy=original.Copy();copy.Name.Outline.Width=7;copy.Details.DistanceText.Outline.Opacity=10;copy.LockText.Outline.Enabled=false;copy.Bar.TextOutline.Enabled=false;Check(original.Name.Outline.Width==3&&original.Details.DistanceText.Outline.Opacity==45&&original.LockText.Outline.Enabled&&original.Bar.TextOutline.Enabled,"Text style snapshots cannot change another bar or undo state");var json=new JavaScriptSerializer();var saved=EnemyHealthOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{enemyHealth=original})));Check(saved.OnlyLocked&&saved.Name.Outline.Width==3&&saved.Details.DistanceText.Outline.Opacity==45&&saved.LockText.Outline.Enabled&&saved.Bar.TextOutline.Enabled,"Selection and every text outline survive save/load");var invalid=new EnemyNameOptions{Outline=null};invalid.Normalize();invalid.Outline.Width=100;invalid.Outline.Opacity=-5;invalid.Normalize();Check(invalid.Outline.Width==8&&invalid.Outline.Opacity==0,"Malformed or legacy outline settings have bounded defaults");var core=new Rectangle(100,200,420,6);var plain=original.Name.Copy();plain.Outline.Enabled=false;var a=EnemyNameOverlay.CaptionBounds(core,plain);var b=EnemyNameOverlay.CaptionBounds(core,original.Name);Check(b.Contains(a)&&b.Width==a.Width+6&&b.Height==a.Height+6,"Text surfaces include the full outline without moving the text anchor");
        using(var renderer=new CrispOverlayText())using(var plainImage=TextSample(renderer,0,100))using(var thin=TextSample(renderer,1,100))using(var thick=TextSample(renderer,4,100))using(var faint=TextSample(renderer,4,25))using(var zero=TextSample(renderer,4,0)){
            Check(DarkPixels(thick)>DarkPixels(thin)&&DarkPixels(thin)>DarkPixels(plainImage),"Genuine glyph border expands with thickness");int maxFaint=0;for(int y=0;y<faint.Height;y++)for(int x=0;x<faint.Width;x++){var pixel=faint.GetPixel(x,y);if(pixel.R<10&&pixel.G<10&&pixel.B<10)maxFaint=Math.Max(maxFaint,pixel.A);}Check(maxFaint>0&&maxFaint<=64,"Outline opacity adjusts alpha without dimming glyphs");for(int y=0;y<zero.Height;y++)for(int x=0;x<zero.Width;x++)Check(zero.GetPixel(x,y)==plainImage.GetPixel(x,y),"Zero outline intensity preserves old text pixels");
            var folder=Path.Combine(root,"designs");Directory.CreateDirectory(folder);using(var compare=new Bitmap(760,150))using(var g=Graphics.FromImage(compare)){g.Clear(Color.FromArgb(219,215,196));g.DrawImageUnscaled(plainImage,0,10);g.DrawImageUnscaled(thin,250,10);g.DrawImageUnscaled(thick,500,10);compare.Save(Path.Combine(folder,"enemy-text-outline-comparison.png"));}
        }
    }
    internal static void Replay(string root,string frames){
        var json=new JavaScriptSerializer();string flow=null;double first=0;foreach(var line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);if(Convert.ToString(row["opcode"])!="0238")continue;string hex=Convert.ToString(row["hex"]);var b=Hex(hex);uint actor,target,skill;if(EnemyHealthSignal.Aim(b,0,b.Length,out actor,out target,out skill)&&actor==1923){flow=Convert.ToString(row["stream"]);first=Convert.ToDouble(row["ts"]);break;}}
        Check(flow!=null,"Replay must contain independently verified self1923 aim");double seed=first;foreach(var line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);if(Convert.ToString(row["stream"])==flow){seed=Convert.ToDouble(row["ts"]);break;}}var signal=new EnemyHealthSignal();signal.Configure(true);Feed(signal,Energy(1923),seed-.01,flow);int tab=0,clear=0,area=0;foreach(var line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);var b=Hex(Convert.ToString(row["hex"]));double t=Convert.ToDouble(row["ts"]);string key=Convert.ToString(row["stream"]);if(key==flow&&first-t>600)continue;Feed(signal,b,t,key);if(key!=flow)continue;int op=(b[0]<<8)|b[1];uint id,actor,target,skill;if(op==0x3438&&EnemyHealthSignal.Selection(b,0,b.Length,out id)){if(id==0){clear++;Check(signal.Read()==null,"Captured clear removes target");}else tab++;}if(op==0x0238&&EnemyHealthSignal.Aim(b,0,b.Length,out actor,out target,out skill)&&actor==1923&&target==34411&&skill==15110340){var sample=signal.Read();Check(sample!=null&&sample.Actor==34411&&sample.Maximum==119700,"Captured unlocked area cast selects principal NPC with observed max");area++;}}
        Check(tab>0&&clear>0&&area>0,"Replay requires actual Tab, clear and isolated area test");File.WriteAllText(Path.Combine(root,"enemy-health-replay-test.txt"),"PASS: captured Tab and clear; unlocked Atadura invernal principal target34411/max119700; passive/HP/death handling. Self1923 supplied from independently verified research session identity.");
    }
    static byte[] Hex(string hex){var b=new byte[hex.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(hex.Substring(i*2,2),16);return b;}
